"use client";

import Link from "next/link";
import { ExternalLinkIcon, LogOutIcon, ShieldIcon, UserIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { UserAvatar } from "@/components/user-avatar";

export function UserMenu({
  name,
  email,
  roleLabel,
  avatar,
  logout,
}: {
  name: string;
  email: string;
  roleLabel: string;
  /** DiceBear data URI generated by the server layout (adminAvatar()); initials are shown without it. */
  avatar?: string | null;
  logout: () => Promise<void>;
}) {
  const initials = name
    .split(/\s+/)
    .map((p) => p[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="sm" className="gap-2 px-1.5">
          <span className="sr-only">Account menu: </span>
          <span className="sr-only sm:hidden">{name}</span>
          {avatar ? (
            <UserAvatar src={avatar} size={28} />
          ) : (
            <span className="flex size-7 items-center justify-center rounded-full bg-accent text-xs font-semibold text-accent-foreground">
              {initials || "A"}
            </span>
          )}
          <span className="hidden text-left leading-tight sm:block">
            <span className="block text-sm">{name}</span>
            <span className="block text-[11px] text-muted-foreground">{roleLabel}</span>
          </span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-56">
        <DropdownMenuLabel className="flex items-center gap-2.5 font-normal">
          {avatar ? <UserAvatar src={avatar} size={40} /> : null}
          <span className="grid min-w-0">
            <span className="truncate text-sm font-medium text-foreground">{name}</span>
            <span className="truncate text-xs text-muted-foreground">{email}</span>
          </span>
        </DropdownMenuLabel>
        <DropdownMenuSeparator />
        <DropdownMenuItem asChild>
          <Link href="/admin/account">
            <UserIcon /> My account
          </Link>
        </DropdownMenuItem>
        <DropdownMenuItem asChild>
          <Link href="/admin/account#mfa">
            <ShieldIcon /> Two-factor authentication
          </Link>
        </DropdownMenuItem>
        <DropdownMenuItem asChild>
          <a href="/" target="_blank" rel="noopener">
            <ExternalLinkIcon /> View public site
          </a>
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <form action={logout}>
          <DropdownMenuItem asChild variant="destructive">
            <button type="submit" className="w-full">
              <LogOutIcon /> Sign out
            </button>
          </DropdownMenuItem>
        </form>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
